    static int checks, scenarios, tickChecks;
    static final BatteryPackItem PACK=new BatteryPackItem(new Item.Properties());
    static void check(boolean v,String m){if(!v)throw new AssertionError(m);checks++;}
    static void perTick(boolean v,String m){check(v,m);tickChecks++;}
    static void scenario(){scenarios++;}
    static Level world(){UniNodespace.levels.clear();UniNodespace.activeNodeNets.clear();Level l=new Level();l.manualClock=true;l.time=1;new CompressorRecipes().deleteRecipes();new CompressorRecipes().registerDefaults();Fluids.initializeGoal14CFuels();return l;}
    static MachineCompressorBlockEntity compressor(Level l,int x){BlockPos p=new BlockPos(x,0,0);BlockState s=new BlockState();var b=new MachineCompressorBlockEntity(p,s);l.states.put(p,s);l.put(b);return b;}
    static MachineDieselBlockEntity diesel(Level l,int x,FluidType type,int fuel){BlockPos p=new BlockPos(x,0,0);BlockState s=new BlockState();var b=new MachineDieselBlockEntity(p,s);l.states.put(p,s);l.put(b);b.tank.setTankType(type);b.tank.setFill(fuel);b.isOn=true;return b;}
    static ItemStack identifier(FluidType t){ItemStack s=new ItemStack(NtmItems.FLUID_IDENTIFIER_MULTI.get());FluidIDMultiItem.setType(s,t,true);return s;}
    static ItemStack pack(long n){ItemStack s=MetaHelper.newStack(PACK,1,BatteryPackType.CAPACITOR_COPPER.ordinal());PACK.setCharge(s,n);return s;}
    static ItemStack upgrade(UpgradeType t,int n){return new ItemStack(new MachineUpgradeItem(new Item.Properties(),t,n));}
    static Player player(Level l){Player p=new Player();p.world=l;p.level=l;p.getInventory().player=p;return p;}
    static void input(MachineCompressorBlockEntity b,FluidType t,int p,int amount){b.tanks[0].setTankType(t);b.tanks[0].withPressure(p);b.setupTanks();b.tanks[0].setFill(amount);b.recalculateUpgrades();}
    static void tick(Level l,MachineCompressorBlockEntity b){l.time++;b.updateEntity();}
    static void nbt(LoadedBaseBlockEntity b,CompoundTag t,boolean load)throws Exception{Class<?> c=b.getClass();while(c!=null){try{Method m=c.getDeclaredMethod(load?"loadAdditional":"saveAdditional",CompoundTag.class,HolderLookup.Provider.class);m.setAccessible(true);m.invoke(b,t,null);return;}catch(NoSuchMethodException e){c=c.getSuperclass();}}throw new AssertionError("NBT missing");}
    static void control(Player p,BlockPos pos,CompoundTag t){CompoundTagControl.handleServer(new CompoundTagControl(t,pos),new IPayloadContext(){public Player player(){return p;}});}
    static CompoundTag pressure(int n){CompoundTag t=new CompoundTag();t.putInt("compression",n);return t;}
    static void net(Level l){UniNodespace.updateNodespace(new MinecraftServer(List.of(l)));UniNodespace.updateNodespace(new MinecraftServer(List.of(l)));}
    static void fluid(IFluidStandardTransceiverMK2 from,IFluidStandardReceiverMK2 to,FluidType type,int p,int n){long before=from.getFluidAvailable(type,p);FluidNetMK2 f=new FluidNetMK2(type);f.addProvider(from);f.addReceiver(to);f.update();check(before-from.getFluidAvailable(type,p)==n,"real fluid network provider debit "+type.getInternalName()+"/"+p);check(f.fluidTracker==n,"real fluid network accepted amount "+n);}
    static void defaultsAndAtomic(){
        scenario();Level l=world();var b=compressor(l,0);check(b.power==0&&b.progress==0&&!b.isOn&&b.getContainerSize()==4&&b.getMaxPower()==100000,"machine defaults");check(b.tanks.length==2&&b.tanks[0].getTankType()==Fluids.NONE&&b.tanks[0].getPressure()==0&&b.tanks[1].getTankType()==Fluids.NONE&&b.tanks[1].getPressure()==1,"NONE pressure defaults");for(var t:b.tanks)check(t.getMaxFill()==16000,"fixed capacity");b.power=100000;tick(l,b);check(b.progress==0&&b.power==100000&&!b.isOn,"NONE cannot process");
        scenario();input(b,Fluids.WATER,0,1000);b.power=2500;b.progress=5;tick(l,b);check(b.power==2500&&b.progress==0&&!b.isOn&&b.tanks[0].getFill()==1000,"strict equal2500 refuses resets");b.power=2501;tick(l,b);check(b.power==1&&b.progress==1&&b.isOn&&b.tanks[0].getFill()==1000&&b.tanks[1].getFill()==0,"2501 starts but no early material debit");tick(l,b);check(b.progress==0&&!b.isOn&&b.power==1,"later underpower resets");
        for(int amount:new int[]{0,999}){scenario();b.power=100000;b.progress=9;b.tanks[0].setFill(amount);tick(l,b);check(b.tanks[0].getFill()==amount&&b.tanks[1].getFill()==0&&b.progress==0&&b.power==100000,"insufficient complete input "+amount);}
        for(int fill:new int[]{15001,16000,16001,Integer.MAX_VALUE}){scenario();b.tanks[0].setFill(1000);b.tanks[1].setFill(fill);b.progress=99;tick(l,b);check(b.tanks[0].getFill()==1000&&b.tanks[1].getFill()==fill&&b.power==100000&&b.progress==0,"full/overcap/overflow output atomic "+fill);}
        scenario();b.tanks[1].setFill(15000);b.progress=99;tick(l,b);check(b.tanks[0].getFill()==0&&b.tanks[1].getFill()==16000&&b.power==97500&&b.progress==0,"exact free capacity completion");
        Object[][] rows={{Fluids.PETROLEUM,0,2000,Fluids.PETROLEUM,2000,1,20},{Fluids.PETROLEUM,1,2000,Fluids.LPG,1000,0,20},{Fluids.BLOOD,3,1000,Fluids.HEAVYOIL,250,0,200},{Fluids.PERFLUOROMETHYL,0,1000,Fluids.PERFLUOROMETHYL,1000,1,50},{Fluids.PERFLUOROMETHYL,1,1000,Fluids.PERFLUOROMETHYL_COLD,1000,0,50}};
        for(Object[] r:rows){scenario();b=compressor(l,(int)r[1]+10+scenarios);input(b,(FluidType)r[0],(int)r[1],(int)r[2]);b.power=100000;check(b.processTime==(int)r[6]&&b.tanks[1].getTankType()==r[3]&&b.tanks[1].getPressure()==(int)r[5],"special setup/time");b.progress=(int)r[6]-2;tick(l,b);check(b.tanks[0].getFill()==(int)r[2]&&b.tanks[1].getFill()==0,"special before completion retains complete input");tick(l,b);check(b.tanks[0].getFill()==0&&b.tanks[1].getFill()==(int)r[4]&&b.power==95000,"special completion exact amounts and cost");}
        scenario();new CompressorRecipes().deleteRecipes();b=compressor(l,100);input(b,Fluids.PETROLEUM,0,1000);b.power=100000;b.progress=99;tick(l,b);check(b.processTime==100&&b.tanks[0].getFill()==0&&b.tanks[1].getFill()==1000&&b.tanks[1].getTankType()==Fluids.PETROLEUM&&b.tanks[1].getPressure()==1,"empty table keeps generic rule");
        scenario();CompressorRecipes.recipes.put(new RecipeKey(Fluids.WATER,0),new CompressorRecipe(1000,Fluids.WATER,Integer.MAX_VALUE,1,1));input(b,Fluids.WATER,0,1000);b.tanks[1].setFill(1);b.power=100000;tick(l,b);check(b.tanks[0].getFill()==1000&&b.tanks[1].getFill()==1&&b.power==100000,"overcapacity custom output safely refused");
        new CompressorRecipes().deleteRecipes();for(int pressure=0;pressure<=4;pressure++){scenario();b=compressor(l,200+pressure);input(b,Fluids.LIGHTOIL_CRACK,pressure,1000);b.power=100000;b.progress=99;tick(l,b);check(b.tanks[1].getPressure()==pressure+1&&b.tanks[1].getFill()==1000&&b.tanks[0].getFill()==0,"generic all five input pressures "+pressure);}
    }
    static void upgrades(){
        // Registry declares SPEED/POWER/OVERDRIVE tier1..3. Two slots allow at most two types.
        Level l=world();var b=compressor(l,0);input(b,Fluids.WATER,0,1000);List<ItemStack> choices=new ArrayList<>();choices.add(ItemStack.EMPTY);for(UpgradeType t:new UpgradeType[]{UpgradeType.SPEED,UpgradeType.POWER,UpgradeType.OVERDRIVE})for(int tier=1;tier<=3;tier++)choices.add(upgrade(t,tier));
        for(ItemStack a:choices)for(ItemStack c:choices){scenario();b.slots.set(2,a);b.slots.set(3,c);b.recalculateUpgrades();int speed=0,economy=0,over=0;for(ItemStack s:new ItemStack[]{a,c})if(!s.isEmpty()){var u=(MachineUpgradeItem)s.getItem();if(u.type==UpgradeType.SPEED)speed+=u.tier;if(u.type==UpgradeType.POWER)economy+=u.tier;if(u.type==UpgradeType.OVERDRIVE)over+=u.tier;}speed=Math.min(3,speed);economy=Math.min(3,economy);over=Math.min(9,over);int time=new int[]{100,60,20,10}[speed]/(over+1);check(b.processTime==Math.max(1,time)&&b.powerRequirement==(2500/(economy+1))*(2*over+1),"legal two-slot generic formula "+speed+"/"+economy+"/"+over);input(b,Fluids.BLOOD,3,1000);b.recalculateUpgrades();check(b.processTime==Math.max(1,200/(speed+1)/(over+1)),"special sequential integer floors");input(b,Fluids.WATER,0,1000);}
        scenario();b.slots.set(2,upgrade(UpgradeType.POWER,2));b.slots.set(3,upgrade(UpgradeType.OVERDRIVE,1));b.recalculateUpgrades();check(b.powerRequirement==2499,"2500/3 then times3=2499 floor");
        scenario();CompressorRecipes.recipes.put(new RecipeKey(Fluids.WATER,0),new CompressorRecipe(1000,Fluids.WATER,1000,1,1));b.slots.set(2,upgrade(UpgradeType.SPEED,3));b.slots.set(3,upgrade(UpgradeType.OVERDRIVE,3));b.recalculateUpgrades();check(b.processTime==1,"minimum1 for short custom duration");
        scenario();b.slots.set(2,ItemStack.EMPTY);b.slots.set(3,ItemStack.EMPTY);b.slots.set(1,upgrade(UpgradeType.SPEED,3));b.recalculateUpgrades();check(b.upgradeManager.getLevel(UpgradeType.SPEED)==0,"battery slot never counted as upgrade");
        check(!b.canPlaceItem(2,upgrade(UpgradeType.FORTUNE,3))&&!b.canPlaceItem(3,upgrade(UpgradeType.POWER,0))&&b.canPlaceItem(2,upgrade(UpgradeType.SPEED,3)),"upgrade admission supported positive types");
        // SYNTHETIC manager/API boundaries: the registry has tier1..3 only. These
        // injected tiers exercise the declared cap, not equipable survival combinations.
        for(int syntheticTier:new int[]{9,10}){
            scenario();b.slots.set(1,ItemStack.EMPTY);b.slots.set(2,upgrade(UpgradeType.OVERDRIVE,syntheticTier));b.slots.set(3,ItemStack.EMPTY);input(b,Fluids.LIGHTOIL_CRACK,0,1000);b.recalculateUpgrades();
            check(b.upgradeManager.getLevel(UpgradeType.OVERDRIVE)==9,"SYNTHETIC manager cap9 tier"+syntheticTier);
            check(b.processTime==10&&b.powerRequirement==47500,"SYNTHETIC generic o9 boundary10ticks47500HE tier"+syntheticTier);
        }
    }
    static void menuControl(){
        scenario();Level l=world();var b=compressor(l,0);var other=compressor(l,10);Player p=player(l);var menu=new MachineCompressorMenu(0,p.getInventory(),b);check(menu.slots.size()==40,"four machine36 player slots");int[][] xy={{17,72},{152,72},{52,72},{70,72}};for(int i=0;i<4;i++)check(menu.slots.get(i).x==xy[i][0]&&menu.slots.get(i).y==xy[i][1],"slot placement "+i);
        for(Direction d:Direction.values())check(Arrays.equals(b.getSlotsForFace(d),new int[]{1}),"battery-only automation "+d);check(b.canTakeItemThroughFace(1,pack(0),Direction.DOWN)&&!b.canTakeItemThroughFace(1,pack(1),Direction.DOWN)&&!b.canTakeItemThroughFace(0,identifier(Fluids.WATER),Direction.DOWN),"automation extracts discharged battery only");
        p.getInventory().setItem(0,identifier(Fluids.WATER));menu.quickMoveStack(p,31);check(b.slots.get(0).getItem() instanceof IItemFluidIdentifier,"Shift identifier");p.getInventory().setItem(1,pack(1234));menu.quickMoveStack(p,32);check(PACK.getCharge(b.slots.get(1))==1234,"Shift battery preserves charge");p.getInventory().setItem(2,upgrade(UpgradeType.POWER,2));menu.quickMoveStack(p,33);check(b.slots.get(2).getItem() instanceof MachineUpgradeItem,"Shift upgrade");p.getInventory().setItem(3,new ItemStack(Items.STICK));menu.quickMoveStack(p,34);check(b.slots.get(3).isEmpty(),"Shift ordinary item refused");menu.quickMoveStack(p,1);check(b.slots.get(1).isEmpty(),"Shift battery out");p.getInventory().setItem(9,pack(2468));menu.quickMoveStack(p,4);check(PACK.getCharge(b.slots.get(1))==2468&&p.getInventory().getItem(9).isEmpty(),"four-slot boundary first player slot");b.slots.set(1,ItemStack.EMPTY);
        scenario();control(p,b.getBlockPos(),pressure(1));check(b.tanks[0].getPressure()==0,"C2S no menu refused");p.containerMenu=new MachineCompressorMenu(1,p.getInventory(),other);control(p,b.getBlockPos(),pressure(1));check(b.tanks[0].getPressure()==0,"wrong menu refused");p.containerMenu=menu;p.inReach=false;control(p,b.getBlockPos(),pressure(1));check(b.tanks[0].getPressure()==0,"distance refused");p.inReach=true;
        for(CompoundTag bad:new CompoundTag[]{null,new CompoundTag(),pressure(-1),pressure(5)}){control(p,b.getBlockPos(),bad);check(b.tanks[0].getPressure()==0,"bad range/null action refused");}
        CompoundTag bad=pressure(1);bad.putInt("extra",0);control(p,b.getBlockPos(),bad);check(b.tanks[0].getPressure()==0,"exact tag only");for(Object value:new Object[]{"1",1L,true}){bad=new CompoundTag();if(value instanceof String)bad.putString("compression",(String)value);else if(value instanceof Long)bad.putLong("compression",(Long)value);else bad.putBoolean("compression",true);control(p,b.getBlockPos(),bad);check(b.tanks[0].getPressure()==0,"wrong NBT type refused");}
        scenario();b.slots.set(0,ItemStack.EMPTY);input(b,Fluids.WATER,0,123);b.tanks[1].setFill(456);b.progress=7;b.isOn=true;b.dirty=0;control(p,b.getBlockPos(),pressure(1));check(b.tanks[0].getPressure()==1&&b.tanks[1].getPressure()==2&&b.tanks[0].getFill()==0&&b.tanks[1].getFill()==0&&b.progress==0&&!b.isOn&&b.dirty==1,"C2S one authorized callback changes clears resets saves once");b.tanks[0].setFill(123);b.tanks[1].setFill(456);b.dirty=0;control(p,b.getBlockPos(),pressure(1));b.receiveControl(pressure(2));check(b.tanks[0].getFill()==123&&b.tanks[1].getFill()==456&&b.tanks[0].getPressure()==1&&b.dirty==0,"same identity no clear and no-player callback inert");
        scenario();CompoundTag copy=new CompoundTag();copy.putIntArray("FluidID",new int[]{Fluids.PETROLEUM.getID()});copy.putInt("compression",1);b.pasteSettings(copy,-1,l,p,b.getBlockPos());check(b.tanks[0].getTankType()==Fluids.WATER,"copy bad index refused");b.pasteSettings(copy,0,l,p,b.getBlockPos());check(b.tanks[0].getTankType()==Fluids.PETROLEUM&&b.tanks[1].getTankType()==Fluids.LPG&&b.tanks[1].getPressure()==0&&b.tanks[0].getFill()==0&&b.tanks[1].getFill()==0,"authorized settings retype clears");
        l.isClientSide=true;check(!b.hasPermission(p),"client no authority");l.isClientSide=false;p.world=new Level();p.level=p.world;check(!b.hasPermission(p),"cross-level refused");p.world=l;p.level=l;l.entities.remove(b.getBlockPos());check(!b.hasPermission(p),"replaced BE refused");
    }
