    static void stateLifecycle()throws Exception{
        scenario();Level l=world();var b=compressor(l,0);input(b,Fluids.LIGHTOIL_CRACK,0,0);b.dirty=0;check(b.transferFluid(Fluids.LIGHTOIL_CRACK,0,1234)==0&&b.dirty>0,"idle network fill dirty");b.dirty=0;check(b.transferFluid(Fluids.LIGHTOIL_CRACK,1,10)==10&&b.transferFluid(Fluids.WATER,0,10)==10&&b.dirty==0,"pressure/type rejection unchanged");b.tanks[1].setFill(1200);b.dirty=0;b.useUpFluid(Fluids.LIGHTOIL_CRACK,0,100);check(b.tanks[1].getFill()==1200&&b.dirty==0,"wrong output pressure unchanged");b.useUpFluid(Fluids.LIGHTOIL_CRACK,1,100);check(b.tanks[1].getFill()==1100&&b.dirty>0,"idle output debit dirty");
        // Emulate a save system that only serializes entities after setChanged.
        scenario();b.dirty=0;CompoundTag saved=new CompoundTag();b.setPower(8765);b.progress=8;tick(l,b);check(b.dirty>0,"progress/energy dirty");if(b.dirty>0)nbt(b,saved,false);var c=compressor(l,20);nbt(c,saved,true);check(c.power==b.power&&c.progress==b.progress&&c.tanks[0].getFill()==1234&&c.tanks[1].getFill()==1100&&c.tanks[1].getPressure()==1&&!c.isOn,"dirty-gated NBT restoration");tick(l,c);check(c.progress==b.progress+1,"restored progress resumes");RegistryFriendlyByteBuf buf=new RegistryFriendlyByteBuf();b.serialize(buf);c.deserialize(buf);check(c.power==b.power&&c.progress==b.progress&&c.processTime==b.processTime&&c.powerRequirement==b.powerRequirement&&c.isOn==b.isOn,"buffer state roundtrip");for(int i=0;i<2;i++)check(c.tanks[i].getFill()==b.tanks[i].getFill()&&c.tanks[i].getPressure()==b.tanks[i].getPressure()&&c.tanks[i].getTankType()==b.tanks[i].getTankType(),"buffer tank roundtrip");
        scenario();b.setPower(-1);check(b.power==0,"lower power clamp");b.setPower(Long.MAX_VALUE);check(b.power==100000,"upper power clamp");l.isClientSide=true;long before=b.power;int fill=b.tanks[0].getFill();tick(l,b);check(b.power==before&&b.tanks[0].getFill()==fill,"client never processes");l.isClientSide=false;
        scenario();l=world();b=compressor(l,0);var core=b;input(b,Fluids.WATER,0,0);var cps=b.getConPos();PipeBaseBlockEntity pipe=new PipeBaseBlockEntity(cps[0].makeCompat(),new BlockState());l.put(pipe);pipe.setFluidType(Fluids.WATER);pipe.updateEntity();CableBaseBlockEntity cable=new CableBaseBlockEntity(cps[1].makeCompat(),new BlockState());l.put(cable);cable.updateEntity();net(l);tick(l,b);net(l);check(UniNodespace.activeNodeNets.stream().anyMatch(n->n instanceof FluidNetMK2&&((FluidNetMK2)n).receiverEntries.containsKey(core)),"actual port pipe subscription");check(UniNodespace.activeNodeNets.stream().anyMatch(n->n instanceof PowerNetMK2&&((PowerNetMK2)n).receiverEntries.containsKey(core)),"actual port cable subscription");
        b.onChunkUnloaded();check(UniNodespace.activeNodeNets.stream().noneMatch(n->n.receiverEntries.containsKey(core)||n.providerEntries.containsKey(core)),"unload removes fluid/power memberships");tick(l,b);net(l);check(UniNodespace.activeNodeNets.stream().anyMatch(n->n.receiverEntries.containsKey(core)),"old-model resubscribe");b.slots.set(0,identifier(Fluids.LIGHTOIL_CRACK));tick(l,b);check(UniNodespace.activeNodeNets.stream().noneMatch(n->n instanceof FluidNetMK2&&((FluidNetMK2)n).receiverEntries.containsKey(core)),"identifier removes stale fluid subscription immediately");b.setRemoved();check(UniNodespace.activeNodeNets.stream().noneMatch(n->n.receiverEntries.containsKey(core)||n.providerEntries.containsKey(core)),"removed unsubscribes");
    }
    static final class Supply {
        final Level l; final List<MachineDieselBlockEntity> engines=new ArrayList<>();final PowerNetMK2 network=new PowerNetMK2();long gross,discarded,consumed,transfers;int burned;
        Supply(Level l,int count,FluidType type,int fuel,IEnergyReceiverMK2... loads){this.l=l;for(int i=0;i<count;i++){var g=diesel(l,100+i*4,type,fuel);engines.add(g);network.addProvider(g);}for(var load:loads)network.addReceiver(load);}
        void step(MachineCompressorBlockEntity... loads){
            for(var g:engines){long old=g.power;int fuel=g.tank.getFill();g.updateEntity();int n=fuel-g.tank.getFill();long gen=n*MachineDieselBlockEntity.getHEFromFuel(g.tank.getTankType());burned+=n;gross+=gen;discarded+=old+gen-g.power;network.addProvider(g);}
            for(var b:loads)network.addReceiver(b);long tracker=network.energyTracker;network.update();transfers+=network.energyTracker-tracker;
            for(var b:loads){long old=b.power;tick(l,b);consumed+=old-b.power;}
        }
        long buffers(){long n=0;for(var g:engines)n+=g.power;return n;}
        int fuelLeft(){int n=0;for(var g:engines)n+=g.tank.getFill();return n;}
    }
    static void underAndSustained(Path work)throws Exception{
        List<String> accounts=new ArrayList<>();for(FluidType fuel:new FluidType[]{Fluids.GASOLINE,Fluids.DIESEL}){
            scenario();Level l=world();var b=compressor(l,0);input(b,Fluids.LIGHTOIL_CRACK,0,1000);Supply supply=new Supply(l,1,fuel,120,b);boolean started=false,reset=false;
            for(int t=0;t<120;t++){int old=b.progress;supply.step(b);started|=b.progress>0;reset|=old>0&&b.progress==0&&!b.isOn;perTick(b.tanks[0].getFill()==1000&&b.tanks[1].getFill()==0,"single engine cannot finish generic100 "+t);}
            check(started&&reset&&supply.gross==120*MachineDieselBlockEntity.getHEFromFuel(fuel)&&supply.fuelLeft()==0,"under-supply starts then resets "+fuel.getInternalName());check(supply.gross==supply.consumed+supply.discarded+supply.buffers()+b.power,"single engine closed accounting");accounts.add("{\"scenario\":\"single_"+fuel.getInternalName()+"\",\"initialHE\":0,\"initialFuelMB\":120,\"grossHE\":"+supply.gross+",\"consumedHE\":"+supply.consumed+",\"discardedHE\":"+supply.discarded+",\"finalBuffersHE\":"+(supply.buffers()+b.power)+",\"progressReset\":true}");
        }
        scenario();Level l=world();var b=compressor(l,0);input(b,Fluids.LIGHTOIL_CRACK,0,1000);Supply supply=new Supply(l,3,Fluids.GASOLINE,100,b);for(int t=0;t<100;t++){supply.step(b);perTick(t==99||b.progress==t+1,"3 gasoline sustained no reset "+t);}check(b.tanks[0].getFill()==0&&b.tanks[1].getFill()==1000&&supply.consumed==250000,"3 gasoline complete true2500/t");check(supply.gross==supply.consumed+supply.discarded+supply.buffers()+b.power,"sustained closed accounting");accounts.add("{\"scenario\":\"three_gasoline\",\"initialHE\":0,\"initialFuelMB\":300,\"grossHE\":"+supply.gross+",\"consumedHE\":"+supply.consumed+",\"discardedHE\":"+supply.discarded+",\"finalBuffersHE\":"+(supply.buffers()+b.power)+",\"producedMB\":1000}");Files.writeString(work.resolve("supply-accounting.json"),"["+String.join(",",accounts)+"]");
    }
    static void desh(Path work)throws Exception{
        scenario();Level l=world();ChemicalPlantRecipes.INSTANCE.deleteRecipes();ChemicalPlantRecipes.INSTANCE.registerDefaults();var b=compressor(l,0);input(b,Fluids.LIGHTOIL_CRACK,0,1000);Supply supply=new Supply(l,3,Fluids.GASOLINE,100,b);for(int i=0;i<100;i++)supply.step(b);
        var plant=new MachineChemicalPlantBlockEntity(new BlockPos(50,0,0),new BlockState());l.put(plant);plant.chemicalModule.recipe="chem.deshcracked";plant.updateEntity();check(plant.inputTanks[0].getTankType()==Fluids.LIGHTOIL_CRACK&&plant.inputTanks[0].getPressure()==1,"actual chemical recipe setup pressure1");check(plant.transferFluid(Fluids.LIGHTOIL_CRACK,0,1000)==1000&&plant.transferFluid(Fluids.WATER,1,1000)==1000,"chemical rejects ordinary pressure and wrong fluid");fluid(b,plant,Fluids.LIGHTOIL_CRACK,1,1000);check(plant.inputTanks[0].getFill()==1000&&b.tanks[1].getFill()==0,"pressure1 actual network conserves1000");plant.transferFluid(Fluids.MERCURY,0,200);plant.slots.set(4,new ItemStack(NtmItems.POWDER_DESH_MIX.get(),2));plant.power=25000;long initial=25000;
        int ticks=0;long cost=0;while((plant.slots.get(7).isEmpty()||plant.slots.get(7).getCount()<2)&&ticks<220){long old=plant.power;plant.updateEntity();cost+=old-plant.power;ticks++;l.time++;}
        check(plant.slots.get(7).is(NtmItems.INGOT_DESH.get())&&plant.slots.get(7).getCount()==2&&plant.slots.get(4).isEmpty()&&plant.inputTanks[0].getFill()==0&&plant.inputTanks[1].getFill()==0,"two actual desh batches consume2mix1000oil200Hg");check(cost==20000&&ticks==200,"actual two100tick chemical costs separate");long finals=supply.buffers()+b.power+plant.power;check(initial+supply.gross==finals+supply.consumed+cost+supply.discarded,"desh finite closed energy accounting");Files.writeString(work.resolve("desh-accounting.json"),"{\"initialHE\":25000,\"initialGasolineMB\":300,\"initialLightoilCrackMB\":1000,\"initialMixItems\":2,\"initialMercuryMB\":200,\"grossHE\":"+supply.gross+",\"compressorHE\":"+supply.consumed+",\"chemicalHE\":"+cost+",\"networkFluidMB\":1000,\"discardedHE\":"+supply.discarded+",\"finalBuffersHE\":"+finals+",\"deshItems\":2,\"upstreamOilChainRerun\":false}");
    }
    static void lpg(Path work)throws Exception{
        scenario();Level l=world();var a=compressor(l,0);var b=compressor(l,20);input(a,Fluids.PETROLEUM,0,4000);input(b,Fluids.PETROLEUM,1,0);Supply supply=new Supply(l,5,Fluids.GASOLINE,80,a,b);FluidNetMK2 between=new FluidNetMK2(Fluids.PETROLEUM);between.addProvider(a);between.addReceiver(b);long transferred=0;boolean simultaneous=false;int completed=0;
        // Two sequential input batches make a real overlapping interval for the 5000HE/t design.
        for(int t=0;t<80;t++){supply.step(a,b);simultaneous|=a.isOn&&b.isOn;between.addProvider(a);between.addReceiver(b);long old=between.fluidTracker;between.update();transferred+=between.fluidTracker-old;if(b.tanks[1].getFill()==2000){completed=t+1;break;}}
        check(simultaneous&&completed>0&&a.tanks[0].getFill()==0&&a.tanks[1].getFill()==0&&b.tanks[0].getFill()==0&&b.tanks[1].getFill()==2000&&transferred==4000,"two real stages4000p0->4000p1->2000LPGp0 overlapping");check(supply.consumed==200000,"4 batches20ticks2500HE=200000");check(supply.gross==supply.consumed+supply.discarded+supply.buffers()+a.power+b.power,"two compressor finite energy accounting");
        var generator=diesel(l,50,Fluids.LPG,0);fluid(b,generator,Fluids.LPG,0,2000);check(generator.tank.getFill()==2000&&b.tanks[1].getFill()==0,"LPG network transfer normal pressure");var socket=new BatterySocketBlockEntity(new BlockPos(60,0,0),new BlockState());l.put(socket);socket.slots.set(0,pack(0));PowerNetMK2 harvest=new PowerNetMK2();long lpgGross=0,clipped=0,external=0;
        long unit=MachineDieselBlockEntity.getHEFromFuel(Fluids.LPG);check(unit>0,"source-extracted final LPG trait accepted");
        for(int i=0;i<2000;i++){long old=generator.power;generator.updateEntity();lpgGross+=unit;clipped+=old+unit-generator.power;harvest.addProvider(generator);harvest.addReceiver(socket);long tracked=harvest.energyTracker;harvest.update();external+=harvest.energyTracker-tracked;l.time++;perTick(generator.power>=0&&generator.power<=generator.getMaxPower()&&socket.getPower()>=0&&socket.getPower()<=socket.getMaxPower(),"LPG capacities "+i);}
        check(generator.tank.getFill()==0&&socket.getPower()>0&&external==socket.getPower(),"real LPG diesel drives actual battery interface");check(lpgGross==generator.power+socket.getPower()+clipped,"LPG generation clipped loss explicitly accounted");long finalHE=supply.buffers()+a.power+b.power+generator.power+socket.getPower();check(supply.gross+lpgGross==supply.consumed+supply.discarded+clipped+finalHE,"whole LPG finite conservation");Files.writeString(work.resolve("lpg-accounting.json"),"{\"initialHE\":0,\"initialPetroleumMB\":4000,\"initialGasolineMB\":400,\"startingGasolineRemainingMB\":"+supply.fuelLeft()+",\"startupGrossHE\":"+supply.gross+",\"compressorHE\":"+supply.consumed+",\"pressure1TransferredMB\":"+transferred+",\"lpgGeneratedMB\":2000,\"lpgBurnedMB\":2000,\"lpgHEPerMB\":"+unit+",\"lpgGrossHE\":"+lpgGross+",\"externalBatteryHE\":"+external+",\"discardedHE\":"+(supply.discarded+clipped)+",\"finalBuffersHE\":"+finalHE+",\"simultaneousDefault5000HE\":true,\"upstreamOilChainRerun\":false}");
    }
    static void exactLpg(Path work)throws Exception{
        scenario();Level l=world();var a=compressor(l,0);var b=compressor(l,20);input(a,Fluids.PETROLEUM,0,2000);input(b,Fluids.PETROLEUM,1,0);Supply supply=new Supply(l,5,Fluids.GASOLINE,40,a,b);FluidNetMK2 between=new FluidNetMK2(Fluids.PETROLEUM);int ticks=0;while(b.tanks[1].getFill()==0&&ticks<40){supply.step(a,b);between.addProvider(a);between.addReceiver(b);between.update();ticks++;}check(a.tanks[0].getFill()==0&&a.tanks[1].getFill()==0&&b.tanks[0].getFill()==0&&b.tanks[1].getFill()==1000&&b.tanks[1].getPressure()==0&&between.fluidTracker==2000,"exact finite single batch2000p0->2000p1->1000LPGp0");check(supply.consumed==100000&&supply.gross==supply.consumed+supply.discarded+supply.buffers()+a.power+b.power,"exact single LPG two20ticks energy closed");Files.writeString(work.resolve("lpg-single-batch-accounting.json"),"{\"initialHE\":0,\"initialGasolineMB\":200,\"remainingGasolineMB\":"+supply.fuelLeft()+",\"initialPetroleumMB\":2000,\"pressure1TransferredMB\":2000,\"lpgProducedMB\":1000,\"grossHE\":"+supply.gross+",\"compressorHE\":"+supply.consumed+",\"discardedHE\":"+supply.discarded+",\"finalBuffersHE\":"+(supply.buffers()+a.power+b.power)+",\"ticks\":"+ticks+"}");
    }
    public static void main(String[] args)throws Exception{Path work=Path.of(args[0]);FluidContainerRegistry.register();defaultsAndAtomic();upgrades();menuControl();nonCoreMenu();stateLifecycle();underAndSustained(work);desh(work);exactLpg(work);lpg(work);System.out.println("Goal14C actual machine/menu/control/network/chains: "+checks+" checks; "+scenarios+" independent scenarios; "+tickChecks+" repeated tick assertions included in checks");}
